installer-gui-script.script:
function adobe_present() {
  // Creative Cloud apps create this folder; without it there is no
  // Premiere Pro to load the panel.
  if (system.files.fileExistsAtPath('/Library/Application Support/Adobe')) return true;
  my.result.title = 'Adobe Premiere Pro is not installed';
  my.result.message = 'Install Premiere Pro from Creative Cloud first, then run this installer again.';
  my.result.type = 'Fatal';
  return false;
}
